```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.ResultSet;
import java.sql.Statement;
import java.sql.SQLException;

public class VulnerableDatabaseAccess {
    public void getUserData(String userId) {
        Connection conn = null;
        Statement stmt = null;
        ResultSet rs = null;
        try {
            // Establishing a connection to the database
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");
            stmt = conn.createStatement();

            // Vulnerable to SQL Injection
            String query = "SELECT * FROM users WHERE user_id = '" + userId + "'";
            rs = stmt.executeQuery(query);

            while (rs.next()) {
                System.out.println("User ID: " + rs.getString("user_id"));
                System.out.println("User Name: " + rs.getString("user_name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                if (rs != null) rs.close();
                if (stmt != null) stmt.close();
                if (conn != null) conn.close();
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
    }
}
```

***
```java
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

public class SecureDatabaseAccess {
    public void getUserData(String userId) {
        Connection conn = null;
        PreparedStatement pstmt = null;
        ResultSet rs = null;
        try {
            // Establishing a connection to the database
            conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "password");

            // Using PreparedStatement to prevent SQL Injection
            String query = "SELECT * FROM users WHERE user_id = ?";
            pstmt = conn.prepareStatement(query);
            pstmt.setString(1, userId);
            rs = pstmt.executeQuery();

            while (rs.next()) {
                System.out.println("User ID: " + rs.getString("user_id"));
                System.out.println("User Name: " + rs.getString("user_name"));
            }
        } catch (SQLException e) {
            e.printStackTrace();
        } finally {
            try {
                if (rs != null) rs.close();
                if (pstmt != null) pstmt.close();
                if (conn != null) conn.close();
            } catch (SQLException e) {
                e.printStackTrace();
            }
        }
    }
}
```

In the first snippet, the code is vulnerable to SQL Injection because it directly concatenates user input into the SQL query. The second snippet fixes this vulnerability by using a `PreparedStatement`, which safely handles user input.

